import {buildIndex,normalize,searchEntries,csv} from './engine.js';
const $=id=>document.getElementById(id),roman=['I','II','III','IV','V','VI','VII'],posNames={ADJ:'Adjective',ADP:'Adposition',ADV:'Adverb',AUX:'Auxiliary verb',CCONJ:'Coordinating conjunction',DET:'Determiner',INTJ:'Interjection',NOUN:'Noun',NUM:'Numeral',PART:'Particle',PRON:'Pronoun',PROPN:'Proper noun',SCONJ:'Subordinating conjunction',VERB:'Verb',X:'Other'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let corpus,index,glosses={},visible=100,entries=[];
function glossFor(word,mode){const lemmas=mode==='lemma'?[word]:[...(index.forms.get(word)||[])],found=[];for(const lemma of lemmas){const gloss=glosses[normalize(lemma).replace(/v/g,'u')];if(gloss&&!found.includes(gloss))found.push(gloss);}return found.slice(0,2).join(' · ');}
function partsOfSpeech(entry,mode){const lemmas=mode==='lemma'?[entry.lemma]:[...(index.forms.get(entry.lemma)||[])];return new Set(lemmas.flatMap(lemma=>[...(index.lemmas.get(lemma)?.pos||[])]));}
function render(){const query=$('wordQuery').value,book=Number($('wordScope').value),mode=$('wordMode').value,sort=$('wordSort').value,posFilter=$('wordPos').value;entries=searchEntries(index,query,book,mode).filter(entry=>!posFilter||partsOfSpeech(entry,mode).has(posFilter));if(sort==='alphabetical')entries.sort((a,b)=>a.lemma.localeCompare(b.lemma)||b.occurrences.length-a.occurrences.length);const shown=entries.slice(0,visible);$('wordHint').textContent=`${entries.length.toLocaleString()} ${mode==='lemma'?'lemmas':'spellings'} · ${book?`Book ${roman[book-1]}`:'all seven books'} · ${mode==='lemma'?'inflections grouped by lemma':'each spelling counted separately'}. Click a row to see its canon contexts.`;$('wordRows').innerHTML=shown.map((entry,i)=>{const forms=new Map();for(const o of entry.occurrences)forms.set(o.form,(forms.get(o.form)||0)+1);const pos=partsOfSpeech(entry,mode),posFull=[...pos].map(tag=>posNames[tag]||tag).join(' · ');const samples=[...forms].sort((a,b)=>b[1]-a[1]).slice(0,4),more=forms.size-samples.length,first=entry.occurrences[0],url=`./index.html?word=${encodeURIComponent(entry.lemma)}&mode=${mode}#canon=${first.canon}`,gloss=glossFor(entry.lemma,mode);return `<tr><td class="rank">${(i+1).toLocaleString()}</td><td><a class="frequency-row" href="${url}"><span class="latin-word" lang="la">${esc(entry.lemma)}</span><span class="english-gloss${gloss?'':' missing-gloss'}" lang="en" title="${esc(gloss||'No dictionary gloss; open the English canon context')}">${gloss?esc(gloss):'No dictionary gloss · view English context ↗'}</span></a></td><td><span class="pos-badge" title="${esc(posFull||'Part of speech unavailable')}" aria-label="${esc(posFull||'Part of speech unavailable')}">${esc([...pos].slice(0,2).join(' · ')||'—')}</span></td><td><div class="form-samples">${samples.map(([form,count])=>`<span class="form-sample" lang="la" title="${count} occurrences">${esc(form)}</span>`).join('')}${more?`<span class="form-more">+${more} forms</span>`:''}</div></td><td class="numeric word-count">${entry.occurrences.length.toLocaleString()}</td></tr>`}).join('')||'<tr><td colspan="5" class="table-loading">No Latin words found. Try another spelling or expand the book scope.</td></tr>';$('showMore').hidden=visible>=entries.length;$('showMore').textContent=`Show more words (${(entries.length-visible).toLocaleString()} remaining)`;}
function download(){const mode=$('wordMode').value,book=Number($('wordScope').value);const rows=[['Latin '+mode,'English gloss','Occurrences','Canons','Attested forms','Part of speech'],...entries.map(e=>{const forms=new Map();let pos=new Set();for(const o of e.occurrences){forms.set(o.form,(forms.get(o.form)||0)+1);for(const lemma of (mode==='lemma'?[e.lemma]:index.forms.get(e.lemma)||[]))for(const p of index.lemmas.get(lemma)?.pos||[])pos.add(p);}return[e.lemma,glossFor(e.lemma,mode)||'No dictionary gloss; see English canon context',e.occurrences.length,new Set(e.occurrences.map(o=>o.canon)).size,[...forms].sort((a,b)=>b[1]-a[1]).map(([f,n])=>`${f} (${n})`).join('; '),[...pos].join(' · ')||'—'];})];const blob=new Blob(['\uFEFF'+csv(rows)],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`canon-law-latin-${mode}-frequencies${book?`-book-${roman[book-1].toLowerCase()}`:''}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function init(){try{const [corpusResponse,glossResponse]=await Promise.all([fetch('./data/corpus.json'),fetch('./data/latin-glosses.json')]);if(!corpusResponse.ok)throw new Error('Corpus request failed');corpus=await corpusResponse.json();if(glossResponse.ok){const data=await glossResponse.json();glosses=data;}index=buildIndex(corpus);$('wordScope').insertAdjacentHTML('beforeend',corpus.books.map(b=>`<option value="${b.id}">Book ${roman[b.id-1]} · ${esc(b.en)}</option>`).join(''));const availablePos=new Set([...index.lemmas.values()].flatMap(entry=>[...entry.pos]));$('wordPos').insertAdjacentHTML('beforeend',[...availablePos].sort((a,b)=>(posNames[a]||a).localeCompare(posNames[b]||b)).map(pos=>`<option value="${esc(pos)}">${esc(posNames[pos]||pos)}</option>`).join(''));$('wordQuery').value=new URLSearchParams(location.search).get('q')||'';for(const id of ['wordQuery','wordScope','wordMode','wordSort','wordPos'])$(id).addEventListener(id==='wordQuery'?'input':'change',()=>{visible=100;render();});$('showMore').addEventListener('click',()=>{visible+=100;render();});$('exportWords').addEventListener('click',download);render();}catch(error){console.error(error);$('wordHint').textContent='The Latin word index could not be loaded. Refresh this page to try again.';$('wordRows').innerHTML='<tr><td colspan="5" class="table-loading">Unable to load the corpus.</td></tr>';}}
init();
